  botUsername: 'agent',
  password: 'test',
  gatewayUrl: deriveGatewayUrl('localhost'),
  autoReconnect: true,
  autoLaunchBrowser: false,
});
await sdk.connect();
await sdk.waitForCondition(s => s !== null && s.inGame, 15000);
const bot = new BotActions(sdk);

const sleep = (ms: number) => new Promise(r => setTimeout(r, ms));
const startXp = sdk.getSkillXp('Defence');
const startTime = Date.now();
const end = startTime + maxMin * 60_000;
