async function navTo(x, z, tol=3, timeoutMs=15000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    const s = sdk.getState();
    const dx = Math.abs(s.player.worldX - x), dz = Math.abs(s.player.worldZ - z);
    if (dx <= tol && dz <= tol) return true;
    try { await bot.walkTo(x, z, tol); } catch(e) {}
    await sdk.waitForTicks(3);
  }
  return false;
}
